namespace ghidra.app.plugin.core.equate;

using ghidra.framework.cmd;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util;

/**
 * Command for removing all references to an equate.
 */
class RemoveEquateCmd : Command<Program> {

	private string[] equateNames;

	private string msg;

	/**
	 * Constructor
	 * @param equateNames one or more equate names to be removed.
	 */
	RemoveEquateCmd(params string[] equateNames) {
		this.equateNames = equateNames;
	}

	/**
	 * The name of the edit action.
	 */
	/* @Override */
	public string getName() {
		return "Remove Equate" + (equateNames.length > 1 ? "s" : "");
	}

	/* @Override */
	public bool applyTo(Program program) {

		EquateTable etable = program.getEquateTable();
		bool success = true;
		foreach (string name in equateNames) {
			if (!etable.removeEquate(name)) {
				Msg.error(this, "Failed to remove equate: " + name);
				success = false;
			}
		}
		if (!success) {
			msg = "Failed to remove one or more equates";
		}
		return success;
	}

	/* @Override */
	public string getStatusMsg() {
		return msg;
	}

}
